INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'basic', 'multiple_choice', 'A dye house needs to prepare a stock solution: dissolving 500 g of dye into 10 liters of water. What is the resulting concentration in g/L?', '["50 g/L","500 g/L","5 g/L","10 g/L"]'::jsonb, '50 g/L', 'Concentration = mass (g) / volume (L) = 500 / 10 = 50 g/L.', 1, '{"stock-solution-calc"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'basic', 'multiple_choice', 'A dye house needs to prepare a stock solution: dissolving 750 g of dye into 15 liters of water. What is the resulting concentration in g/L?', '["50 g/L","750 g/L","5 g/L","15 g/L"]'::jsonb, '50 g/L', 'Concentration = mass (g) / volume (L) = 750 / 15 = 50 g/L.', 1, '{"stock-solution-calc"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'From a 50 g/L dye stock solution, how many liters must be taken to obtain exactly 2 kg (2,000 g) of dye?', '["40 liters","50 liters","25 liters","100 liters"]'::jsonb, '40 liters', 'Volume needed = mass required / concentration = 2,000 g / 50 g/L = 40 liters.', 2, '{"stock-solution-volume-calc"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'From a 25 g/L dye stock solution, how many liters must be taken to obtain exactly 1.5 kg (1,500 g) of dye?', '["60 liters","25 liters","37.5 liters","15 liters"]'::jsonb, '60 liters', 'Volume needed = mass required / concentration = 1,500 g / 25 g/L = 60 liters.', 2, '{"stock-solution-volume-calc"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'basic', 'multiple_choice', 'A finishing process applies a resin add-on of 8% (by weight) to fabric. For 1,200 kg of fabric, how many kg of resin (dry basis) are added?', '["96 kg","8 kg","150 kg","1,104 kg"]'::jsonb, '96 kg', 'Resin add-on = 8% × fabric weight = 0.08 × 1,200 kg = 96 kg.', 1, '{"resin-addon-calc"}'::text[]);
